(function() {
    'use strict';

    class MacroAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Pa\u00eds en Tus Manos';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title_en: 'Round 1 — Diagnosis and Initial Policy Package',
                    title_es: 'Ronda 1 — Diagn\u00f3stico y Paquete de Pol\u00edtica Inicial',
                    desc_en: 'You have been appointed Director of the Consejo de Pol\u00edtica Econ\u00f3mica. Argentina faces annual inflation above 80%, GDP growth stalling at 0.8%, unemployment rising to 11.4%, and a current account deficit straining foreign currency reserves to just 2.8 months of imports.<br><br>Design your initial macroeconomic stabilization package: set fiscal targets, the BCRA policy rate, exchange rate crawling peg pace, and decide whether to accept IMF support.',
                    desc_es: 'Ha sido nombrado Director del Consejo de Pol\u00edtica Econ\u00f3mica. Argentina enfrenta inflaci\u00f3n anual superior al 80%, crecimiento del PIB estancado en 0.8%, desempleo en aumento al 11.4% y un d\u00e9ficit de cuenta corriente que presiona las reservas a solo 2.8 meses de importaciones.<br><br>Dise\u00f1e su paquete de estabilizaci\u00f3n macroecon\u00f3mica inicial: defina metas fiscales, la tasa de pol\u00edtica del BCRA, el ritmo del crawling peg y decida si acepta el apoyo del FMI.'
                },
                {
                    title_en: 'Round 2 — Commodity Shock Response',
                    title_es: 'Ronda 2 — Respuesta al Shock de Commodities',
                    desc_en: 'Your first policy package has taken effect. However, a global commodity price shock has reduced soy export earnings by 18%, straining the current account and putting pressure on reserves.<br><br>How will you adjust your policy mix in response? Consider whether to absorb the shock through reserves, adjust fiscal policy, or modify monetary stance.',
                    desc_es: 'Su primer paquete de pol\u00edticas ha entrado en vigor. Sin embargo, un shock global de precios de commodities ha reducido los ingresos por exportaciones de soja en un 18%, tensionando la cuenta corriente y presionando las reservas.<br><br>\u00bfC\u00f3mo ajustar\u00e1 su combinaci\u00f3n de pol\u00edticas? Considere si absorber el shock con reservas, ajustar la pol\u00edtica fiscal o modificar la postura monetaria.'
                },
                {
                    title_en: 'Round 3 — Stabilization or Crisis?',
                    title_es: 'Ronda 3 — \u00bfEstabilizaci\u00f3n o Crisis?',
                    desc_en: 'The economy is at a critical juncture. Evaluate the trajectory of inflation expectations, reserve levels, and your credibility score.<br><br>If credibility is strong, the economy may be stabilizing. If weak, speculative pressure and expectation de-anchoring could trigger a crisis. Choose carefully: double down on discipline, pivot toward growth, or seek additional external financing.',
                    desc_es: 'La econom\u00eda est\u00e1 en un momento cr\u00edtico. Eval\u00fae la trayectoria de las expectativas de inflaci\u00f3n, los niveles de reservas y su puntaje de credibilidad.<br><br>Si la credibilidad es fuerte, la econom\u00eda puede estar estabiliz\u00e1ndose. Si es d\u00e9bil, la presi\u00f3n especulativa y el desanclaje de expectativas podr\u00edan desencadenar una crisis. Elija cuidadosamente: reforzar la disciplina, girar hacia el crecimiento o buscar financiamiento externo adicional.'
                },
                {
                    title_en: 'Round 4 — Final Outcome',
                    title_es: 'Ronda 4 — Resultado Final',
                    desc_en: 'This is your final round as Director. Your macroeconomic legacy will be measured against the stabilization targets: inflation below 35%, GDP growth above 2.5%, unemployment below 9%, reserves above 5 months, and fiscal balance at or above zero.<br><br>Make your last policy adjustments wisely.',
                    desc_es: 'Esta es su ronda final como Director. Su legado macroecon\u00f3mico se medir\u00e1 contra las metas de estabilizaci\u00f3n: inflaci\u00f3n por debajo del 35%, crecimiento del PIB superior al 2.5%, desempleo inferior al 9%, reservas superiores a 5 meses y balance fiscal en cero o superior.<br><br>Realice sus \u00faltimos ajustes de pol\u00edtica con prudencia.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    gdpGrowth: 0.8,
                    inflation: 82,
                    unemployment: 11.4,
                    fiscalBalance: -2.1,
                    currentAccount: -1.8,
                    reserves: 2.8,
                    exchangeRate: 1200,
                    publicDebt: 135,
                    credibility: 30,
                    inflationExpectations: 75,
                    imfStatus: 0,
                    taylorGap: 0,
                    activeShock: '',
                    gdpHistory: [],
                    inflationHistory: [],
                    unemploymentHistory: [],
                    reservesHistory: [],
                    expectationsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    fiscalTarget: -1,
                    policyRate: 97,
                    crawlingPeg: 3.5,
                    imfDecision: 2
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var fiscalInput = document.getElementById('fiscalInput');
            if (fiscalInput) decisions.fiscalTarget = parseFloat(fiscalInput.value);

            var rateInput = document.getElementById('rateInput');
            if (rateInput) decisions.policyRate = parseFloat(rateInput.value);

            var pegSelect = document.getElementById('pegSelect');
            if (pegSelect) decisions.crawlingPeg = parseFloat(pegSelect.value);

            var imfSelect = document.getElementById('imfSelect');
            if (imfSelect) decisions.imfDecision = parseInt(imfSelect.value);

            if (isNaN(decisions.fiscalTarget) || decisions.fiscalTarget < -3 || decisions.fiscalTarget > 2) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('fiscal_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.policyRate) || decisions.policyRate < 60 || decisions.policyRate > 130) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('rate_warning'), 'warning'
                );
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var outputGap = ds.gdpGrowth - 2.0;
            var taylorRate = Math.round(2.5 + ds.inflation + 0.5 * (ds.inflation - 25) + 0.5 * outputGap);
            var taylorGap = d.policyRate - taylorRate;

            var realRate = d.policyRate - ds.inflation;

            var multiplier = 0.8;
            if (ds.gdpGrowth < 0) multiplier = 1.2;
            if (ds.publicDebt > 120) multiplier *= 0.7;
            var fiscalImpulse = d.fiscalTarget - ds.fiscalBalance;

            var annualizedPeg = d.crawlingPeg * 12;
            var realDepreciation = annualizedPeg - ds.inflation;

            var credibilityBoost = 0;
            var reserveBoost = 0;
            var imfStatus = ds.imfStatus;

            if (d.imfDecision === 2) {
                credibilityBoost = 12;
                reserveBoost = 1.0;
                imfStatus = 2;
            } else if (d.imfDecision === 1) {
                credibilityBoost = 4;
                reserveBoost = 0.3;
                imfStatus = 1;
            } else {
                if (ds.imfStatus === 0) credibilityBoost = -5;
                imfStatus = Math.max(0, ds.imfStatus - 1);
            }

            var shockGDP = 0;
            var shockInflation = 0;
            var shockReserves = 0;
            var shockCredibility = 0;
            var activeShock = '';

            if (round === 1 && Math.random() < 0.30) {
                activeShock = 'drought';
                shockGDP = -0.8;
                shockReserves = -0.5;
            }
            if (round === 2 && Math.random() < 0.45) {
                activeShock = 'fed_hike';
                shockReserves = -0.8;
                shockGDP = -0.3;
            }
            if (round === 3) {
                if (Math.random() < 0.25) {
                    activeShock = 'political_crisis';
                    shockCredibility = -15;
                    shockGDP = -0.5;
                }
                if (Math.random() < 0.35) {
                    activeShock = activeShock ? activeShock + '+inflation_surprise' : 'inflation_surprise';
                    shockInflation = 15;
                }
            }
            if (round === 4 && Math.random() < 0.25) {
                activeShock = 'commodity_rally';
                shockGDP = 0.6;
                shockReserves = 0.8;
            }

            var monetaryGDPEffect = 0;
            if (realRate > 0) {
                monetaryGDPEffect = -realRate * 0.035;
            } else {
                monetaryGDPEffect = -realRate * 0.015;
            }
            var fiscalGDPEffect = fiscalImpulse * multiplier * 0.5;
            var tradeGDPEffect = realDepreciation * 0.015;

            var newGDP = ds.gdpGrowth + fiscalGDPEffect + monetaryGDPEffect + tradeGDPEffect + shockGDP;
            newGDP = Math.max(-5, Math.min(8, Math.round(newGDP * 10) / 10));

            var inertia = 0.45;
            var expectWeight = 0.30;
            var anchorWeight = 0.25;
            var baseInflation = inertia * ds.inflation + expectWeight * ds.inflationExpectations + anchorWeight * 25;

            var demandPressure = 0;
            if (newGDP > 2.0) {
                demandPressure = (newGDP - 2.0) * 2.5;
            } else {
                demandPressure = (newGDP - 2.0) * 1.2;
            }

            var monetaryInflEffect = 0;
            if (taylorGap > 0) {
                monetaryInflEffect = -taylorGap * 0.18;
            } else {
                monetaryInflEffect = -taylorGap * 0.10;
            }

            var exchangePassthrough = 0;
            if (annualizedPeg > ds.inflation) {
                exchangePassthrough = (annualizedPeg - ds.inflation) * 0.25;
            }

            var credEffect = -(ds.credibility + credibilityBoost - 30) * 0.12;

            var newInflation = baseInflation + demandPressure + monetaryInflEffect + exchangePassthrough + credEffect + shockInflation;
            newInflation = Math.max(2, Math.round(newInflation * 10) / 10);

            var adaptiveWeight = Math.max(0.3, 1 - (ds.credibility + credibilityBoost) / 120);
            var newExpectations = adaptiveWeight * newInflation + (1 - adaptiveWeight) * 25;
            newExpectations = Math.round(newExpectations * 10) / 10;

            var unemploymentChange = -0.5 * (newGDP - 2.0);
            var newUnemployment = ds.unemployment + unemploymentChange;
            newUnemployment = Math.max(3, Math.min(25, Math.round(newUnemployment * 10) / 10));

            var tradeEffect = realDepreciation * 0.025;
            var importEffect = newGDP > 2 ? -0.3 : 0.4;
            var newCurrentAccount = ds.currentAccount + tradeEffect + importEffect;
            if (round === 2) newCurrentAccount -= 0.6;
            newCurrentAccount = Math.max(-5, Math.min(3, Math.round(newCurrentAccount * 10) / 10));

            var newReserves = ds.reserves + newCurrentAccount * 0.25 + reserveBoost + shockReserves;
            if (annualizedPeg < ds.inflation * 0.8) newReserves -= 0.4;
            newReserves = Math.max(0.5, Math.round(newReserves * 10) / 10);

            var newCredibility = ds.credibility + credibilityBoost + shockCredibility;
            if (taylorGap > 5) newCredibility += 5;
            if (taylorGap < -10) newCredibility -= 8;
            if (d.fiscalTarget >= 0) newCredibility += 5;
            if (d.fiscalTarget < -2) newCredibility -= 5;
            if (newInflation < ds.inflation) newCredibility += 3;
            newCredibility = Math.max(0, Math.min(100, Math.round(newCredibility)));

            var newExchangeRate = Math.round(ds.exchangeRate * (1 + d.crawlingPeg / 100 * 3));

            var newDebt = ds.publicDebt - d.fiscalTarget * 0.8 + (d.policyRate * 0.01 - newGDP * 0.01) * 5;
            newDebt = Math.max(50, Math.round(newDebt * 10) / 10);

            ds.gdpGrowth = newGDP;
            ds.inflation = newInflation;
            ds.unemployment = newUnemployment;
            ds.fiscalBalance = d.fiscalTarget;
            ds.currentAccount = newCurrentAccount;
            ds.reserves = newReserves;
            ds.exchangeRate = newExchangeRate;
            ds.publicDebt = newDebt;
            ds.credibility = newCredibility;
            ds.inflationExpectations = newExpectations;
            ds.imfStatus = imfStatus;
            ds.taylorGap = taylorGap;
            ds.activeShock = activeShock;

            ds.gdpHistory.push(newGDP);
            ds.inflationHistory.push(newInflation);
            ds.unemploymentHistory.push(newUnemployment);
            ds.reservesHistory.push(newReserves);
            ds.expectationsHistory.push(newExpectations);

            var self = this;
            var nextPeriod = round + 1;
            setTimeout(function() {
                if (nextPeriod <= self.ROUNDS.length) {
                    self._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
                var shockEl = document.getElementById('shockAlert');
                if (shockEl) {
                    if (activeShock) {
                        shockEl.style.display = 'block';
                        shockEl.innerHTML = window.mySimulation.t('shock_' + activeShock.split('+')[0]) || activeShock;
                    } else {
                        shockEl.style.display = 'none';
                    }
                }
            }, 500);

            return {
                period: round,
                gdpGrowth: newGDP,
                inflation: newInflation,
                unemployment: newUnemployment,
                fiscalBalance: d.fiscalTarget,
                reserves: newReserves,
                currentAccount: newCurrentAccount,
                exchangeRate: newExchangeRate,
                credibility: newCredibility,
                taylorRate: taylorRate,
                taylorGap: taylorGap,
                publicDebt: newDebt,
                activeShock: activeShock,
                policyRate: d.policyRate,
                crawlingPeg: d.crawlingPeg,
                imfDecision: d.imfDecision
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('gdpDisplay', 'domainState.gdpGrowth', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('inflationDisplay', 'domainState.inflation', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('unemploymentDisplay', 'domainState.unemployment', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('reservesDisplay', 'domainState.reserves', function(v) { return v.toFixed(1); });
            uiManager.bind('fiscalDisplay', 'domainState.fiscalBalance', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('currentAccountDisplay', 'domainState.currentAccount', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('taylorGapDisplay', 'domainState.taylorGap', function(v) { return (v > 0 ? '+' : '') + Math.round(v) + 'pp'; });
            uiManager.bind('credibilityDisplay', 'domainState.credibility', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('exchangeRateDisplay', 'domainState.exchangeRate', function(v) { return Math.round(v).toLocaleString(); });
            uiManager.bind('debtDisplay', 'domainState.publicDebt', function(v) { return v.toFixed(1) + '%'; });
        }

        getChartConfig() {
            var _t = function(k, f){ try { return window.mySimulation.t(k); } catch(e){ return f; } };
            return {
                inflationChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: _t('chart_inflation_series','Inflation (%)'),
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231,76,60,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: _t('chart_expectations_series','Expectations (%)'),
                                data: [],
                                borderColor: '#f39c12',
                                backgroundColor: 'rgba(243,156,18,0.05)',
                                borderWidth: 2,
                                borderDash: [6, 3],
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: _t('chart_inflation_title','Inflation Dynamics') }
                        },
                        scales: { y: { beginAtZero: false } }
                    }
                },
                realEconomyChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: _t('chart_gdp_series','GDP Growth (%)'),
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2
                            },
                            {
                                label: _t('chart_unemployment_series','Unemployment (%)'),
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.05)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: _t('chart_realecon_title','Real Economy') }
                        },
                        scales: { y: { beginAtZero: false } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.gdpHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                inflationChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.inflationHistory },
                        { data: state.domainState.expectationsHistory }
                    ]
                },
                realEconomyChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.gdpHistory },
                        { data: state.domainState.unemploymentHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var last = history[history.length - 1];
            var r = last.results || {};
            var finalInflation = (r.inflation != null) ? r.inflation : 82;
            var finalGDP = (r.gdpGrowth != null) ? r.gdpGrowth : 0.8;
            var finalUnemployment = (r.unemployment != null) ? r.unemployment : 11.4;
            var finalReserves = (r.reserves != null) ? r.reserves : 2.8;
            var finalFiscal = (r.fiscalBalance != null) ? r.fiscalBalance : -2.1;

            var inflScore = Math.max(0, Math.min(100, (82 - finalInflation) / (82 - 35) * 100));
            var gdpScore = Math.max(0, Math.min(100, (finalGDP - 0.8) / (2.5 - 0.8) * 100));
            var unempScore = Math.max(0, Math.min(100, (11.4 - finalUnemployment) / (11.4 - 9) * 100));
            var fiscalScore = Math.max(0, Math.min(100, (finalFiscal + 2.1) / (0 + 2.1) * 100));
            var reserveScore = Math.max(0, Math.min(100, (finalReserves - 2.8) / (5 - 2.8) * 100));

            var totalScore = Math.round(
                inflScore * 0.30 +
                gdpScore * 0.25 +
                unempScore * 0.20 +
                fiscalScore * 0.15 +
                reserveScore * 0.10
            );

            var _t = function(k){ try { return window.mySimulation.t(k); } catch(e){ return k; } };
            var performance = _t('perf_crisis');
            if (totalScore > 70) performance = _t('perf_excellent');
            else if (totalScore > 50) performance = _t('perf_competent');
            else if (totalScore > 30) performance = _t('perf_struggling');

            var insights = [];
            if (finalInflation <= 35) {
                insights.push(_t('insight_infl_success'));
            } else if (finalInflation <= 55) {
                insights.push(_t('insight_infl_partial'));
            } else {
                insights.push(_t('insight_infl_high'));
            }

            if (finalGDP >= 2.5) {
                insights.push(_t('insight_gdp_strong'));
            } else if (finalGDP < 0) {
                insights.push(_t('insight_gdp_recession'));
            }

            if (finalReserves >= 5) {
                insights.push(_t('insight_reserves_strong'));
            } else if (finalReserves < 2) {
                insights.push(_t('insight_reserves_low'));
            }

            return {
                totalScore: totalScore,
                inflationScore: Math.round(inflScore),
                gdpScore: Math.round(gdpScore),
                unemploymentScore: Math.round(unempScore),
                fiscalScore: Math.round(fiscalScore),
                reserveScore: Math.round(reserveScore),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.taylorGap < -15) return window.mySimulation.t('hint_taylor_loose');
            if (results.inflation > state.domainState.inflation) return window.mySimulation.t('hint_inflation_rising');
            if (results.reserves < 2) return window.mySimulation.t('hint_reserves_critical');
            if (results.credibility < 20) return window.mySimulation.t('hint_credibility_low');
            if (results.gdpGrowth < -1) return window.mySimulation.t('hint_recession');
            if (results.inflation < 40 && results.gdpGrowth > 1.5) return window.mySimulation.t('hint_good_progress');
            return null;
        }

